const icon = name => `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.source}"/></svg>`;
const badge=(text,type='')=>`<span class="badge ${type}">${e(text)}</span>`;
const btn=(label,action,ic='',cls='',attrs='')=>`<button class="btn ${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${e(label)}</button>`;
const link=(label,url,ic='external',cls='btn')=>`<a class="${cls}" href="${e(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${e(label)}${icon(ic)}</a>`;
const empty=(title,body,action,label,ic='bag')=>`<div class="empty-state"><div class="empty-icon">${icon(ic)}</div><h2>${e(title)}</h2><p>${e(body)}</p>${action?btn(label,action,'plus','primary'):''}</div>`;
const option=(value,label,current)=>`<option value="${e(value)}"${String(value)===String(current)?' selected':''}>${e(label)}</option>`;
const field=(label,name,value='',type='text',extra='',hint='')=>`<label class="field"><span>${e(label)}</span><input type="${type}" name="${name}" value="${e(value)}" ${extra}>${hint?`<small>${e(hint)}</small>`:''}</label>`;
const selectField=(label,name,values,current,extra='')=>`<label class="field"><span>${e(label)}</span><select name="${name}" ${extra}>${values.map(v=>Array.isArray(v)?option(v[0],v[1],current):option(v,v,current)).join('')}</select></label>`;
const textarea=(label,name,value='',hint='',extra='')=>`<label class="field ${extra}"><span>${e(label)}</span><textarea name="${name}">${e(value)}</textarea>${hint?`<small>${e(hint)}</small>`:''}</label>`;
let taxonomy, library, buildStatus={pages:{}}, referenceGuides=[];
