function safeDecode(value){try{return decodeURIComponent(value);}catch{return value;}}
function route(){const h=location.hash.replace(/^#\/?/,'')||'overview';const [path,q]=h.split('?');const [page,id]=path.split('/');return {page,id:safeDecode(id||''),params:new URLSearchParams(q||'')};}
function go(page,params={}){let q=new URLSearchParams(params).toString();location.hash=`/${page}${q?'?'+q:''}`;}
function rowById(id){return taxonomy.rows.find(x=>x.id===id);}
function planFor(id){return {pageBuilt:"No",animatedHeader:"No",...(buildStatus.pages[id]||{}),...(ws.pagePlans[id]||{})};}
function categoryOptions(current='',emptyLabel='Select a category'){return option('',emptyLabel,current)+taxonomy.rows.filter(r=>r.system==='editorial'||r.system==='shop').map(r=>{const ancestors=r.isTopLevel?[]:[...new Set([r.rootName,r.parentName].filter(Boolean))];return option(r.id,`${r.system==='shop'?'Shop':'Editorial'} · ${[...ancestors,r.name].join(' / ')}`,current);}).join('');}
function externalIcon(url,label='Open source page'){return `<a class="icon-btn external-link" href="${e(safeUrl(url))}" target="_blank" rel="noopener noreferrer" aria-label="${e(label)}">${icon('external')}</a>`;}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.innerHTML=icon(error?'alert':'check')+`<span>${e(message)}</span>`;$('#toasts').append(el);setTimeout(()=>el.remove(),6000);}
async function copy(text,message='Copied to clipboard'){try{await navigator.clipboard.writeText(text);toast(message);}catch{openDialog('Copy this text',`<p>Your browser blocked clipboard access. Select and copy the text below.</p><textarea class="prompt-editor" readonly>${e(text)}</textarea>`);}}
function download(name,content,type='application/json'){const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([content],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function csv(rows){return rows.map(r=>r.map(value=>{let text=String(value??'');if(typeof value==='string'&&/^(?:[\t\r\n]|\s*[=+@-])/.test(text))text="'"+text;return `"${text.replaceAll('"','""')}"`;}).join(',')).join('\r\n');}
function openDialog(title,body,narrow=false){const d=$('#dialog');returnFocus=document.activeElement;d.className=narrow?'narrow':'';d.innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${e(title)}</h2><button class="icon-btn" data-action="close-dialog" aria-label="Close dialog">${icon('close')}</button></div><div class="dialog-body">${body}</div>`;if(!d.open)d.showModal();setTimeout(()=>d.querySelector('input:not([type=hidden]),textarea,select')?.focus(),30);}
function closeDialog(){const d=$('#dialog');d.close();d.innerHTML='';returnFocus?.focus?.();}
function unlock(next=null){pendingAction=next;openDialog('Open your workspace',`<p>Use the workspace access code to view and edit shared supplier records, product research and page plans.</p><form id="login-form">${field('Workspace access code','code','','password','required autocomplete="current-password"')}<div id="form-error"></div><div class="form-actions">${btn('Open workspace','submit-login','unlock','primary','type="submit"')}</div></form>${localPreview?'<p class="footer-note">Shared editing is available on the deployed workspace. This preview contains the audited reference data.</p>':''}`,true);}
function ensureAuth(next){if(!authenticated){unlock(next);return false;}next();return true;}
async function api(url,options={}){const r=await fetch(url,{credentials:'same-origin',...options,headers:{'Content-Type':'application/json',...options.headers}});let data;try{data=await r.json();}catch{throw new Error('The server did not return a valid response. Please try again.');}if(!r.ok){const err=new Error(data.error||'The request could not be completed.');err.status=r.status;throw err;}return data;}
async function loadWorkspace(){const r=await api('/api/workspace');ws=r.data;etag=r.etag;}
async function saveWorkspace(change,message){if(busy)throw new Error('Another change is saving. Please wait a moment.');if(!authenticated){unlock();throw new Error('Open your workspace before saving.');}busy=true;updateSync('Saving…');try{const draft=structuredClone(ws);change(draft);draft.activity.unshift({id:uid(),text:message,date:new Date().toISOString()});draft.activity=draft.activity.slice(0,60);const r=await api('/api/workspace',{method:'PUT',body:JSON.stringify({data:draft,etag})});ws=r.data;etag=r.etag;toast(message);return true;}catch(err){if(err.status===409){await loadWorkspace();throw new Error('Someone saved a newer change. Your form is still open. Review your changes and save again.');}if(err.status===401){authenticated=false;throw new Error('Your session expired. Open the workspace again to save.');}throw err;}finally{busy=false;updateSync();}}
function updateSync(text){const el=$('#sync-state');if(el){el.className='sync-state'+(!authenticated?' locked':'');el.innerHTML=icon(authenticated?'check':'lock')+e(text||(authenticated?'Shared workspace':'Reference view'));}const b=$('#access-button');if(b){b.innerHTML=icon(authenticated?'refresh':'unlock')+(authenticated?'Refresh':'Open workspace');b.dataset.action=authenticated?'refresh':'unlock';}}
function shell(){const r=route();const active=r.page==='category'?'map':r.page==='prompt'?'prompts':r.page;const label=navItems.find(x=>x[0]===active)?.[1]||(active==='settings'?'Workspace settings':'Workspace');$('#app').innerHTML=`<div class="shell"><button class="mobile-scrim" data-action="menu" aria-label="Close navigation"></button><aside class="sidebar"><a class="brand" href="#/overview" aria-label="Wow Fashion workspace home"><span class="wordmark">WOW<span>FASHION</span></span><span class="brand-divider"></span><span class="brand-label">THE<br>WORKSPACE</span></a><div class="project-label"><span class="dot"></span> A new chapter for Wow Fashion</div><nav aria-label="Main navigation">${navItems.map(([id,title,ic],i)=>`${[0,3,6,8].includes(i)?`<div class="nav-group">${i===0?'The website':i===3?'The collection':i===6?'The words':'The process'}</div>`:''}<a class="nav-link ${active===id?'active':''}" ${active===id?'aria-current="page"':''} href="#/${id}">${icon(ic)}<span>${title}</span>${id==='prompts'?`<span class="nav-count">${library.prompts.length}</span>`:''}</a>`).join('')}</nav><div class="sidebar-bottom"><a class="nav-link ${active==='settings'?'active':''}" href="#/settings">${icon('settings')} Workspace settings</a><a class="nav-link" href="https://wowfashion.com" target="_blank" rel="noopener noreferrer">${icon('external')} Visit the current website</a><div class="workspace-person"><span class="avatar">WF</span><div>Wow Fashion studio<br><span class="muted">Website build · v1.0</span></div></div></div></aside><div class="workarea"><header class="topbar"><button class="icon-btn menu-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="false">${icon('menu')}</button><div class="breadcrumb"><span class="crumb-parent">Workspace</span><span class="crumb-slash">/</span><strong>${e(label)}</strong></div><div class="top-actions"><button class="search-launch" data-action="search" aria-label="Search the workspace">${icon('search')}<span>Search anything</span><kbd>⌘ K</kbd></button><span id="sync-state" class="sync-state"></span><button class="btn small" id="access-button" data-action="unlock"></button></div></header><main id="main" class="content" tabindex="-1"></main></div></div>`;updateSync();renderMain();}
function pageHeader(title,description,actions=''){return `<div class="page-header"><div><h1>${e(title)}</h1><p>${e(description)}</p></div><div class="header-actions">${actions}</div></div>`;}
function renderMain(){const r=route();const views={'product-pages':productPageView,keywords:()=>'<div id="keyword-research"></div>',overview:overviewView,map:mapView,category:categoryView,products:productsView,suppliers:suppliersView,prompts:promptsView,prompt:promptView,guidelines:guidelinesView,roadmap:roadmapView,sources:sourcesView,settings:settingsView};$('#main').innerHTML=`<div class="reveal">${(views[r.page]||overviewView)(r)}</div>`;if(r.page==='keywords')mountResearch($('#keyword-research'),taxonomy.rows);document.title=`${navItems.find(x=>x[0]===r.page)?.[1]||'Workspace'} | Wow Fashion`;}
function overviewView(){const approved=ws.products.filter(x=>x.status==='Approved').length;return `<div class="overview-intro"><div><h1>The next chapter<br>of <em>Wow Fashion.</em></h1><p>Your website, your collection, your point of view.<br>Everything you need to build it, in one place.</p></div><div class="edition"><strong>The website workspace</strong><br>Research snapshot · 7 November 2026<br>Live workspace records update as you work</div></div><div class="stats-strip"><div class="stat"><div class="stat-top"><span class="stat-number">7</span><span class="stat-label">Core departments</span></div><div class="stat-note">106 editorial subcategories</div></div><div class="stat"><div class="stat-top"><span class="stat-number">135</span><span class="stat-label">Shop categories</span></div><div class="stat-note">A separate taxonomy, fully mapped</div></div><div class="stat"><div class="stat-top"><span class="stat-number">${library.prompts.length}</span><span class="stat-label">Ready-to-use prompts</span></div><div class="stat-note">Writing, sourcing and review</div></div><div class="stat"><div class="stat-top"><span class="stat-number">${authenticated?ws.suppliers.length:'0'}</span><span class="stat-label">${authenticated?'Supplier records':'Suppliers in this view'}</span></div><div class="stat-note">${authenticated?approved+' products approved': 'Open workspace for shared records'}</div></div></div><div class="overview-grid"><section class="feature-panel"><span class="feature-stamp" aria-hidden="true">W.</span>${badge('Start with the structure')}<h2>Every category.<br>A clear starting point.</h2><p>The complete website inventory, with page briefs, product shortlists and migration decisions connected.</p><a class="btn" href="#/map">Explore the website map ${icon('arrow')}</a></section><section class="editorial-note"><div class="note-index">${icon('layers')} From the website audit</div><h2>One website.<br>Two overlapping structures.</h2><p>113 editorial pages sit alongside 135 shop-category records. Five URLs overlap. Keep both inventories in view while choosing the new structure.</p><div class="decision-row">${badge('5 URL decisions','amber')}<a class="link-btn" href="#/sources?tab=findings">Review the findings ${icon('arrow')}</a></div><div class="quiet-banner"><div>${icon('info')}</div><p>${ws.settings.businessModel==='undecided'?'The operating model is still open: affiliate, direct retail or hybrid. <a href="#/settings">Record your decision</a> before finalising transactional copy.':'Working model: <strong>'+e(ws.settings.businessModel)+'</strong>. Briefs use this model with '+e(ws.settings.market)+' / '+e(ws.settings.currency)+'. <a href="#/settings">Update the working brief</a>.'}</p></div></section></div><div class="overview-bottom"><section><div class="section-head"><h2>The core collections</h2><span class="muted">Editorial subcategories</span></div><div class="collection-list">${taxonomy.groups.map((g,i)=>`<a class="collection-row" href="#/map?department=${e(g.id)}"><span class="collection-number">${String(i+1).padStart(2,'0')}</span><div><div class="collection-title">${e(g.name)}</div><div class="collection-url">${e(new URL(g.navigationUrl).pathname)}</div></div><span class="collection-total">${g.childCount} subcategories</span>${icon('chevron')}</a>`).join('')}</div></section><section><div class="section-head"><h2>A good place to begin</h2><a class="link-btn" href="#/prompts">All prompts ${icon('arrow')}</a></div>${library.prompts.filter(p=>/category|product.*research|sourcing|supplier/i.test(p.title+' '+p.id)).slice(0,3).map(p=>`<a class="prompt-quick" href="#/prompt/${e(p.id)}">${icon(/supplier|sourcing|research/i.test(p.title)?'search':'pen')}<div><h3>${e(p.title)}</h3><p>${e(p.description)}</p>${badge(p.category)}</div>${icon('arrow')}</a>`).join('')}<div class="subsection"><div class="section-head"><h2>The working standard</h2></div><p class="muted small">Useful fashion advice, honest product evidence and a consistent voice. A proposed standard for every page we create.</p><a class="link-btn" style="margin-top:14px" href="#/guidelines">Read the editorial standards ${icon('arrow')}</a></div>${ws.activity.length?`<div class="subsection"><h3>Latest in the workspace</h3>${ws.activity.slice(0,3).map(a=>`<p class="footer-note">${e(a.text)}<br><span class="small">${e(new Date(a.date).toLocaleString('en-GB'))}</span></p>`).join('')}</div>`:''}</section></div>`;}
function mapView(r){const system=r.params.get('system')||'editorial';const department=r.params.get('department')||filters.department;let rows=taxonomy.rows.filter(x=>x.system===system);const roots=rows.filter(x=>x.isTopLevel);const query=filters.q.toLowerCase();rows=rows.filter(x=>(department==='all'||x.rootId===department)&&(filters.level==='all'||(filters.level==='root'?x.isTopLevel:!x.isTopLevel))&&(filters.status==='all'||(planFor(x.id).status||'Not started')===filters.status)&&(!query||[x.name,x.url,x.parentName,x.rootName].join(' ').toLowerCase().includes(query)));const byParent=new Map();for(const x of rows){let k=x.rootName||x.name; if(!byParent.has(k))byParent.set(k,[]);byParent.get(k).push(x);}rows=[...byParent.keys()].sort().flatMap(k=>byParent.get(k).sort((a,b)=>a.level-b.level||a.name.localeCompare(b.name)));return pageHeader('The website map','Every existing category, with its original URL and hierarchy. Use each page record to plan the new website.',btn('Export inventory','export-categories','download'))+`<div class="tabs" role="tablist" aria-label="Category systems">${[['editorial','Editorial pages',113],['shop','Shop categories',135],['blog','Blog categories',2]].map(([id,title,count])=>`<button role="tab" aria-selected="${system===id}" class="tab ${system===id?'active':''}" data-action="map-system" data-value="${id}">${title}<span class="tab-count">${count}</span></button>`).join('')}</div>${system==='shop'?`<div class="quiet-banner warning">${icon('info')}<p>These 135 WooCommerce taxonomy records are separate from the editorial pages. All 10 root archives were checked live and currently have <strong>noindex</strong>. <a href="#/sources?tab=findings">See migration findings</a>.</p></div>`:system==='editorial'?`<div class="result-info"><span>7 parent pages · 106 subcategories · Source audit: 7 November 2026</span><span>Existing structure, before migration decisions</span></div>`:`<div class="quiet-banner">${icon('book')}<p>These two editorial blog categories are separate from the commercial category inventory.</p></div>`}<div class="toolbar"><label class="field-search">${icon('search')}<span class="sr-only">Search categories</span><input id="filter-query" value="${e(filters.q)}" placeholder="Search by category, parent or URL…" data-filter="q"></label><select aria-label="Filter by department" data-filter="department"><option value="all">All departments</option>${roots.map(x=>option(x.id,x.name,department)).join('')}</select><select aria-label="Filter by level" data-filter="level">${[['all','All levels'],['root','Top-level only'],['child','Subcategories only']].map(x=>option(...x,filters.level)).join('')}</select><select aria-label="Filter by planning status" data-filter="status">${option('all','All statuses',filters.status)+pageStatuses.map(s=>option(s,s,filters.status)).join('')}</select></div><div class="result-info"><span>${rows.length} records shown</span><button class="link-btn" data-action="reset-filters">Reset filters</button></div>${rows.length?`<div class="table-wrap"><table><thead><tr><th>Category / existing URL</th><th>Parent</th><th>${system==='shop'?'Products':'Page type'}</th><th>Planning status</th><th>Has the page been built?</th><th>Does the page feature an animated header?</th><th><span class="sr-only">Open page</span></th></tr></thead><tbody>${rows.map(x=>{let p=planFor(x.id);return `<tr class="${x.isTopLevel?'row-root':''}"><td class="indent-${x.depth}"><a class="table-name" href="#/category/${e(x.id)}">${e(x.name)}</a><span class="url-line">${e(x.path)}</span></td><td class="table-parent">${e(x.parentName||'Top-level')}</td><td>${system==='shop'?`<span class="tabular">${fmt(x.count)}</span>`:badge(x.isTopLevel?'Parent page':'Subcategory','outline')}</td><td>${badge(p.status||'Not started',p.status==='Approved'?'green':p.status==='In review'?'amber':'')}</td><td>${badge(p.pageBuilt,p.pageBuilt==='Yes'?'green':'outline')}${p.previewUrl?`<span class="url-line">${link('View new page',p.previewUrl,'external','link-btn')}</span>`:''}</td><td>${badge(p.animatedHeader,p.animatedHeader==='Yes'?'green':'outline')}</td><td>${externalIcon(x.url,'Visit '+x.name)}</td></tr>`;}).join('')}</tbody></table></div>`:empty('No matching categories','Try another search or reset your filters.','','','search')}<p class="footer-note">All records and parent relationships were confirmed in first-party sources. Fifteen URLs were individually HTTP-checked; each page record shows its own verification detail. Shop product counts are the source snapshot, not newly vetted products. <a href="#/sources">View audit sources</a>.</p>`;}
function categoryView(r){const x=rowById(r.id);if(!x)return empty('Category not found','Return to the website map to select a category.','','','map');const p=planFor(x.id);const children=taxonomy.rows.filter(y=>y.parentId===x.id);const prods=ws.products.filter(y=>productCategories(y).includes(x.id));const collision=taxonomy.collisions.find(c=>c.url===x.url);return `<a class="back-link" href="#/map?system=${x.system}">${icon('back')} Back to the website map</a>`+pageHeader(x.name,`${x.system==='shop'?'Shop taxonomy':x.system==='blog'?'Blog taxonomy':'Editorial page'} · ${x.parentName?'Under '+x.parentName:'Top-level category'}`,link('View current page',x.url)+(!x.isTopLevel&&x.system!=='blog'?`<a class="btn" href="#/keywords?category=${e(x.id)}">Keyword Research</a>`:''))+`<div class="detail-layout"><div>${collision?`<div class="quiet-banner warning">${icon('alert')}<p><strong>This URL belongs to more than one record.</strong> ${e(x.notes?.[0]||'Resolve its role before choosing the new URL.')} <a href="#/sources?tab=findings">Review URL overlaps</a>.</p></div>`:''}<section class="panel"><div class="section-head"><h2>Page plan</h2>${badge(p.status||'Not started')}</div><form id="page-plan-form" data-id="${e(x.id)}"><div class="form-grid">${selectField('Status','status',pageStatuses,p.status||'Not started')}${selectField('Priority','priority',['Unassigned','High','Medium','Low'],p.priority||'Unassigned')}${selectField('Has the page been built?','pageBuilt',['No','Yes'],p.pageBuilt)}${selectField('Does the page feature an animated header?','animatedHeader',['No','Yes'],p.animatedHeader)}${field('New page preview URL','previewUrl',p.previewUrl||'','url')}${field('Owner','owner',p.owner||'')}${field('Target product count','targetProducts',p.targetProducts??8,'number','min="0" max="100" step="1"')}${field('Primary keyword','keyword',p.keyword||'')}${field('Proposed new URL','proposedUrl',p.proposedUrl||'','text','placeholder="/category/ or full URL"','Planning only. This does not change the website.')}${textarea('Brief and migration notes','notes',p.notes||'','Audience, search intent, product criteria, redirect decisions and review notes.','full')}</div><div class="form-actions">${btn('Save page plan','submit-plan','check','primary','type="submit"')}</div><div id="form-error"></div></form></section><section class="subsection"><div class="section-head"><h2>Products for this page</h2>${btn('Add a product','add-product','plus','small',`data-category="${e(x.id)}"`)}</div>${prods.length?productTable(prods):empty('The edit starts here','Research products for this category, capture the evidence and connect them to the supplier directory.','add-product','Add the first product')}<div class="prompt-actions">${btn('Build a category prompt','category-prompt','pen','',`data-id="${e(x.id)}"`)}<a class="btn" href="https://www.aliexpress.com/w/wholesale-${encodeURIComponent(x.name.toLowerCase().replaceAll(' ','-'))}.html" target="_blank" rel="noopener noreferrer">Search AliExpress ${icon('external')}</a></div></section>${children.length?`<section class="subsection"><div class="section-head"><h2>Subcategories</h2><span class="muted">${children.length} children</span></div><div class="collection-list">${children.map(c=>`<a class="collection-row" href="#/category/${e(c.id)}"><span>${icon('map')}</span><div><div class="collection-title">${e(c.name)}</div><div class="collection-url">${e(c.path)}</div></div>${badge(planFor(c.id).status||'Not started')}${icon('chevron')}</a>`).join('')}</div></section>`:''}</div><aside class="detail-aside"><section class="panel"><h2>Source record</h2><dl class="meta-list"><div class="meta-row"><dt>Existing URL</dt><dd><a href="${e(x.url)}" target="_blank" rel="noopener noreferrer">${e(x.path)}</a></dd></div><div class="meta-row"><dt>Parent</dt><dd>${x.parentId?`<a href="#/category/${e(x.parentId)}">${e(x.parentName)}</a>`:'Top-level'}</dd></div><div class="meta-row"><dt>Source ID</dt><dd>${e(x.sourceId)}</dd></div><div class="meta-row"><dt>HTTP status</dt><dd>${x.httpStatus?e(x.httpStatus):'Not individually checked'}</dd></div><div class="meta-row"><dt>Robots</dt><dd>${e(x.robots||'Not individually checked')}</dd></div><div class="meta-row"><dt>Audited</dt><dd>7 November 2026</dd></div></dl></section><section class="panel"><h2>Evidence</h2><p>Record and hierarchy confirmed from the public site. Source verification does not mean a product or supplier is approved.</p>${(x.sources||[]).map((s,i)=>`<p>${link('Source '+(i+1),s,'external','link-btn')}</p>`).join('')}${x.notes?.length?`<ul class="bullet-list">${x.notes.map(n=>`<li>${e(n)}</li>`).join('')}</ul>`:''}</section></aside></div>`;}
function productTable(products){return `<div class="table-wrap"><table><thead><tr><th>Product / supplier</th><th>Page mappings</th><th>Variations</th><th>Price range</th><th>Item rating</th><th>Status / evidence</th><th>Listing</th></tr></thead><tbody>${products.map(p=>{const score=scoreProduct(p),range=priceRange(p);return `<tr><td><button class="table-name product-name" data-action="edit-product" data-id="${e(p.id)}">${e(p.name)}</button><span class="url-line">${e(ws.suppliers.find(x=>x.id===p.supplierId)?.name||'Supplier not linked')}</span></td><td>${productCategories(p).map(id=>`<a class="small" href="#/category/${e(id)}">${e(rowById(id)?.name||id)}</a>`).join('<br>')}${(p.keywordTargets||[]).map(t=>`<div><span class="badge accent">${e(t.keyword)}</span><span class="url-line">Proposed keyword-led page</span></div>`).join('')}</td><td>${p.variants?.length?`<details><summary>${p.variants.length} combinations</summary><ul class="bullet-list">${p.variants.map(v=>`<li>${e([v.colour,v.style,v.size,v.option].filter(Boolean).join(' / ')||v.sku)} · ${v.price==null?'Price unknown':e(p.currency)+' '+Number(v.price).toFixed(2)} · ${e(v.availability||'Unknown')}</li>`).join('')}</ul></details>`:'Not recorded'}</td><td class="tabular">${range.min===null?'Unknown':e(p.currency)+' '+range.min.toFixed(2)+(range.max!==range.min?'–'+range.max.toFixed(2):'')}${range.partial?'<span class="url-line">Some variant prices unknown</span>':''}<span class="url-line">${p.shipping==null?'Shipping not recorded':'+ '+e(p.currency)+' '+Number(p.shipping).toFixed(2)+' shipping (selected variant)'}</span></td><td>${p.rating==null?'—':Number(p.rating).toFixed(2)+' / 5'}<span class="url-line">${p.reviews==null?'Rating count unknown':fmt(p.reviews)+' ratings'}</span></td><td>${badge(p.status||'Researching')}<span class="url-line">${score.total}/100 evidence · ${score.coverage}% coverage</span></td><td>${p.sourceUrl?externalIcon(p.sourceUrl,'Open AliExpress listing'):''}</td></tr>`;}).join('')}</tbody></table></div>`;}
function productsView(r){const view=r.params.get('view')||'shortlist',category=r.params.get('category')||'',supplier=r.params.get('supplier')||'',keyword=r.params.get('keyword')||'',query=filters.q.toLowerCase();if((view==='keyword-map'||keyword)&&!collectionResearch&&!collectionResearchLoading&&!collectionResearchError)loadCollectionResearch();const products=ws.products.filter(p=>(!category||productCategories(p).includes(category))&&(!supplier||p.supplierId===supplier)&&(!keyword||(p.keywordTargets||[]).some(t=>t.slug===keyword))&&(!query||[p.name,...productCategories(p).map(id=>rowById(id)?.name),...(p.keywordTargets||[]).map(t=>t.keyword),...(p.variants||[]).flatMap(v=>[v.colour,v.style,v.size,v.option,v.sku]),ws.suppliers.find(x=>x.id===p.supplierId)?.name,p.notes].join(' ').toLowerCase().includes(query))&&(filters.status==='all'||p.status===filters.status));return pageHeader('Products','Map one listing to its categories and keyword-led pages. Record each variation combination and its price.',btn('Add a product','add-product','plus','primary',category?`data-category="${e(category)}"`:''))+`<div class="tabs" aria-label="Product views">${[['shortlist','All products'],['category-map','Subcategory coverage'],['keyword-map','Keyword-led pages'],['guide','Evidence scoring']].map(([id,label])=>`<button class="tab ${view===id?'active':''}" data-action="product-view" data-value="${id}">${label}</button>`).join('')}</div>${!authenticated?`<div class="quiet-banner">${icon('lock')}<p><button class="link-btn" data-action="unlock">Open your shared workspace</button> to load and save products, variations and suppliers. Counts are shown only after the saved records are loaded.</p></div>`:''}${view==='guide'?scoringGuide():view==='category-map'||view==='keyword-map'?collectionCoverage(view):`<div class="toolbar"><label class="field-search">${icon('search')}<span class="sr-only">Search products</span><input id="filter-query" data-filter="q" value="${e(filters.q)}" placeholder="Search product, variation, supplier or keyword…"></label><select data-action="product-category-filter" aria-label="Product category">${categoryOptions(category,'All categories')}</select><select data-action="product-supplier-filter" aria-label="Product supplier">${option('','All suppliers',supplier)+ws.suppliers.map(x=>option(x.id,x.name,supplier)).join('')}</select><select aria-label="Product status" data-filter="status">${option('all','All statuses',filters.status)+productStatuses.map(x=>option(x,x,filters.status)).join('')}</select>${btn('Export products','export-products','download','small')}${btn('Export variations','export-variants','download','small')}</div>${keyword?`<div class="quiet-banner"><p>Keyword-led page: <strong>${e(collectionResearch?.proposals.find(x=>x.slug===keyword)?.keyword||keyword)}</strong> · Proposed, not an approved live page. <a href="#/products">Clear page filter</a></p></div>`:''}<div class="result-info">${authenticated?fmt(products.length)+' product records':'Saved products are private'}</div>${products.length?productTable(products):empty(authenticated?'No products match this view.':'Your product catalogue','Add a listing once, then map its variants and relevant pages. No products are represented as researched until you add real listing evidence.','add-product','Add a product')}`}`;}
function scoringGuide(){const sc=library.scoring;return `<div class="quiet-banner">${icon('info')}<p><strong>${e(sc.status)}.</strong> ${e(sc.purpose)}</p></div><div class="table-wrap"><table class="rubric-table"><thead><tr><th>Signal</th><th>Weight</th><th>How to assess it</th></tr></thead><tbody>${sc.components.map(c=>`<tr><td><strong>${e(c.label)}</strong></td><td>${c.weight} / 100</td><td>${e(c.guidance)}${c.formula?`<details><summary>Calculation</summary><p class="footer-note">${e(c.formula)}</p></details>`:''}${c.anchors?`<details><summary>Scoring anchors: 0 to 5</summary><ul class="bullet-list">${Object.entries(c.anchors).map(([k,v])=>`<li><strong>${e(k)}:</strong> ${e(v)}</li>`).join('')}</ul></details>`:''}</td></tr>`).join('')}</tbody></table></div><div class="info-columns"><section><h3>Small review samples count less</h3><p>A 5.0 rating from a handful of buyers is adjusted toward a chosen 4.2 prior, with the weight of 50 reviews. The prior is an internal assumption, not a measured AliExpress average.</p></section><section><h3>Unknown never means passed</h3><p>Missing inputs earn no confirmed points. The score always stays out of 100 and shows evidence coverage separately. The result remains incomplete until every component is assessed.</p></section><section><h3>Refresh before publishing</h3><p>Evidence older than 14 days needs refreshing. Recheck price, selected variant and destination availability when you publish. Sales and ratings do not verify a manufacturer.</p></section></div><section class="subsection"><h2>Before a product can move forward</h2><div class="source-grid">${sc.gates.map(g=>`<div class="source-card"><h3>${e(g.label)}</h3><p>${e(g.pass)}</p><span class="small muted">If unknown: ${e(g.unknown)}</span></div>`).join('')}</div></section><section class="subsection"><h2>What each decision means</h2><div class="table-wrap" style="margin-top:18px"><table><thead><tr><th>Decision</th><th>Interpretation</th></tr></thead><tbody>${sc.decisions.map(d=>`<tr><td>${badge(d.label,d.label==='Priority shortlist'?'green':d.label==='Do not shortlist'?'red':'amber')}</td><td>${e(d.condition)}</td></tr>`).join('')}</tbody></table></div></section><p class="footer-note">This is a transparent prioritisation framework, not proof of quality, authenticity or legal compliance. <a href="#/sources?tab=research">View the source and policy references</a>.</p>`;}
function openProduct(id='',category=''){ensureAuth(()=>{const p=ws.products.find(x=>x.id===id)||{categoryId:category||route().id||'',currency:ws.settings.currency||'GBP',destination:ws.settings.market||'',status:'Researching',hardGate:'review'};productKeywordDraft=structuredClone(p.keywordTargets||[]);const grades=[['','Not assessed'],[0,'0 · Documented failure'],[1,'1 · Serious concerns'],[2,'2 · Limited / mixed evidence'],[3,'3 · Usable evidence'],[4,'4 · Strong evidence'],[5,'5 · Corroborated / sample supported']];openDialog(id?'Edit product research':'Research a product',`<p>Create one record per AliExpress listing, with one row for each colour/style/size combination. Missing values remain unknown. The scoring guide explains the evidence needed for each grade.</p><form id="product-form" data-id="${e(id)}"><div class="form-grid">${field('Product name','name',p.name||'','text','required maxlength="200"')}${field('Listing URL','sourceUrl',p.sourceUrl||'','url','required placeholder="https://www.aliexpress.com/item/…"')}<label class="field"><span>Category</span><select name="categoryId" required>${categoryOptions(p.categoryId)}</select></label><label class="field"><span>Supplier</span><select name="supplierId">${option('','Not linked',p.supplierId)+ws.suppliers.map(x=>option(x.id,x.name,p.supplierId)).join('')}</select><small>Add suppliers in the supplier directory.</small></label>${field('Destination','destination',p.destination||'','text','required')}${field('Evidence checked on','evidenceDate',p.evidenceDate||'','date',`required max="${today()}"`)}${field('Reference / selected variant price','price',p.price??'','number','min="0" step="0.01"')}${field('Shipping cost','shipping',p.shipping??'','number','min="0" step="0.01"','Enter 0 only when free shipping was verified.')}${selectField('Currency','currency',['GBP','USD','EUR','CAD','AUD'],p.currency||'GBP')}${selectField('Workflow status','status',productStatuses,p.status||'Researching')}</div>${productMappingFields(p)}${productVariationFields(p)}<div class="form-section"><h3>Rating and demand</h3><p>Use item-level figures. Preserve any “+” or variant limitations in your evidence notes.</p></div><div class="form-grid">${field('Item rating (out of 5)','rating',p.rating??'','number','min="0" max="5" step="0.01"')}${field('Responses behind the rating','reviews',p.reviews??'','number','min="0" step="1"','Use the rating-response count, not an unrelated store total.')}${field('Displayed sold count (lower bound)','sold',p.sold??'','number','min="0" step="1"','For 1,000+ sold, record 1000 and preserve “+” in notes.')}</div><div class="form-section"><h3>Evidence quality</h3><p>Grade observed evidence using the <a href="#/products?view=guide" data-action="close-for-link">scoring anchors</a>. A blank field means not assessed.</p></div><div class="form-grid">${selectField('Recent review evidence','recentReviewScore',grades,p.recentReviewScore??'')}${selectField('Seller evidence','sellerScore',grades,p.sellerScore??'')}${selectField('Fit and specification clarity','specificationScore',grades,p.specificationScore??'')}${selectField('Comparable landed value','valueScore',grades,p.valueScore??'')}${selectField('Delivery and returns clarity','deliveryScore',grades,p.deliveryScore??'')}${selectField('Critical checks','hardGate',[['review','Needs review / missing evidence'],['clear','All critical checks passed'],['reject','A critical check failed']],p.hardGate||'review')}${textarea('Critical check notes','gateNotes',p.gateNotes||'','Exact variant, destination, identity, essential specifications and recurring issue checks.','full')}${textarea('Evidence and research notes','notes',p.notes||'','Record selected size/colour, recent review sample and dates, seller evidence, price comparison, tax caveats and links.','full')}</div><div id="product-score-preview" class="quiet-banner"></div><div id="form-error"></div><div class="form-actions">${id?btn('Delete','delete-product','trash','danger',`data-id="${e(id)}" type="button"`):''}${btn('Cancel','close-dialog','','','type="button"')}${btn('Save product','submit-product','check','primary','type="submit"')}</div></form>`);updateProductScore();loadProductKeywordPicker();});}
const productNumberKeys=['rating','reviews','sold','recentReviewScore','sellerScore','specificationScore','valueScore','deliveryScore','price','shipping'];
function productFormData(form){const d=Object.fromEntries(new FormData(form));delete d.multiCategoryIds;for(const k of productNumberKeys)d[k]=d[k]===''?null:Number(d[k]);d.categoryIds=[...new Set([d.categoryId,...Array.from(form.elements.multiCategoryIds?.selectedOptions||[],x=>x.value)].filter(Boolean))];d.keywordTargets=structuredClone(productKeywordDraft);d.variants=Array.from(form.querySelectorAll('[data-variant-row]'),row=>{const v={id:row.dataset.variantRow};for(const input of row.querySelectorAll('[data-variant-field]'))v[input.dataset.variantField]=input.dataset.variantField==='price'?(input.value===''?null:Number(input.value)):input.value.trim();return v;});return d;}
function updateProductScore(){const form=$('#product-form');if(!form)return;const s=scoreProduct(productFormData(form));$('#product-score-preview').innerHTML=icon('layers')+`<div><strong>${s.total} / 100 confirmed points</strong> · ${s.coverage}% evidence coverage<br>${e(s.eligibility)}${s.reasons?.length?`<p class="small muted">${e(s.reasons.slice(0,3).join(' '))}</p>`:''}</div>`;}
function suppliersView(){const q=filters.q.toLowerCase();const list=ws.suppliers.filter(s=>(!q||[s.name,s.country,s.categories,s.type].join(' ').toLowerCase().includes(q))&&(filters.status==='all'||s.status===filters.status));return pageHeader('Suppliers','See the products each supplier represents, their rating evidence and the details needed for sourcing.',btn('Add a supplier','add-supplier','plus','primary'))+`<div class="toolbar"><label class="field-search">${icon('search')}<span class="sr-only">Search suppliers</span><input id="filter-query" data-filter="q" value="${e(filters.q)}" placeholder="Search supplier, category or country…"></label><select data-filter="status" aria-label="Supplier status">${option('all','All statuses',filters.status)+supplierStatuses.map(x=>option(x,x,filters.status)).join('')}</select>${btn('Export CSV','export-suppliers','download','small')}</div><div class="quiet-banner"><p><strong>Product aggregate rating</strong> = sum of each item rating × its rating count, divided by the total rating count. Missing ratings/counts are excluded. Duplicate listing URLs count once, using the most recently checked record. Variations do not multiply ratings. This is separate from the supplier’s own store rating.</p></div>${!authenticated?`<div class="quiet-banner">${icon('lock')}<p><button class="link-btn" data-action="unlock">Open your workspace</button> to load saved suppliers and product totals.</p></div>`:''}${list.length?`<div class="table-wrap"><table><thead><tr><th>Supplier</th><th>Products / variants</th><th>Aggregate product rating</th><th>Store rating</th><th>Categories</th><th>Contact / checks</th><th>Status</th></tr></thead><tbody>${list.map(s=>{const a=supplierSummary(s.id,ws.products);return `<tr><td><button class="table-name" data-action="edit-supplier" data-id="${e(s.id)}">${e(s.name)}</button><span class="url-line">${e(s.type||'Marketplace seller')} · ${e(s.country||'Location unknown')}</span>${s.url?link('Store',s.url,'external','link-btn'):''}</td><td><a href="#/products?supplier=${e(s.id)}">${a.products} distinct products</a><span class="url-line">${a.variants} variation combinations${a.records!==a.products?' · '+a.records+' records':''}</span></td><td><strong>${a.rating==null?'—':a.rating.toFixed(2)+' / 5'}</strong><span class="url-line">${a.ratedProducts}/${a.products} products · ${fmt(a.reviews)} ratings</span>${a.unratedProducts?`<span class="small muted">${a.unratedProducts} products lack weighting data</span>`:''}</td><td>${s.rating==null?'—':Number(s.rating).toFixed(2)+' / 5'}</td><td>${e(a.categories.map(id=>rowById(id)?.name||id).filter((v,i,a)=>a.indexOf(v)===i).join(', ')||s.categories||'Not recorded')}</td><td>${e(s.contact||'Contact not recorded')}<span class="url-line">Supplier checked: ${e(s.checkedAt||'Unknown')}</span><span class="url-line">Latest product check: ${e(a.latestCheck||'Unknown')}</span><span class="url-line">Sample: ${e(s.sampleStatus||'Not requested')}</span></td><td>${badge(s.status||'Researching')}</td></tr>`;}).join('')}</tbody></table></div>`:empty('Build your supplier directory','Record the store identity, contact details, sourcing notes and sample outcomes. Product counts and aggregate ratings update from linked products.','add-supplier','Add a supplier','users')}`;}
function openSupplier(id=''){ensureAuth(()=>{const s=ws.suppliers.find(x=>x.id===id)||{};openDialog(id?'Supplier record':'Add a supplier',`<p>Start with the public store identity. Mark a manufacturer as verified only when the supporting evidence is recorded.</p><form id="supplier-form" data-id="${e(id)}"><div class="form-grid">${field('Supplier / store name','name',s.name||'','text','required maxlength="200"')}${field('Store or supplier URL','url',s.url||'','url','required placeholder="https://…"')}${selectField('Relationship type','type',['Marketplace seller','Brand','Wholesaler','Manufacturer claimed','Manufacturer verified'],s.type||'Marketplace seller')}${selectField('Status','status',supplierStatuses,s.status||'Researching')}${field('Country / location','country',s.country||'')}${field('Category specialisms','categories',s.categories||'','text','placeholder="Dresses, knitwear…"')}${field('Store trading since','storeSince',s.storeSince||'','text','placeholder="Year, or unknown"')}${field('Store rating (out of 5)','rating',s.rating??'','number','min="0" max="5" step="0.01"')}${field('Published contact / contact page','contact',s.contact||'')}${field('Evidence URL','evidenceUrl',s.evidenceUrl||'','url')}${field('Last checked','checkedAt',s.checkedAt||'','date',`max="${today()}"`)}${selectField('Sample status','sampleStatus',['Not requested','Requested','Received','Passed','Failed'],s.sampleStatus||'Not requested')}${field('Dispatch / delivery lead time','leadTime',s.leadTime||'')}${field('Shipping destinations','shippingDestinations',s.shippingDestinations||'')}${field('Minimum order / terms','orderTerms',s.orderTerms||'')}${textarea('Returns and refund terms','returnsPolicy',s.returnsPolicy||'','Record the source and check date in the notes.','full')}${textarea('Manufacturer evidence','manufacturingEvidence',s.manufacturingEvidence||'','Company identity, facility evidence and source links. A store name alone is insufficient.','full')}${textarea('Due diligence and sample notes','notes',s.notes||'','Store history, response evidence, selected sample/variant, strengths, concerns and next action.','full')}</div><div id="form-error"></div><div class="form-actions">${id?btn('Delete','delete-supplier','trash','danger',`data-id="${e(id)}" type="button"`):''}${btn('Cancel','close-dialog','','','type="button"')}${btn('Save supplier','submit-supplier','check','primary','type="submit"')}</div></form>`);});}
function promptsView(){const groups=['All',...new Set(library.prompts.map(x=>x.category))];const q=filters.q.toLowerCase();const ps=library.prompts.filter(p=>(filters.promptGroup==='All'||p.category===filters.promptGroup)&&(!q||[p.title,p.description,p.category,...(p.tags||[])].join(' ').toLowerCase().includes(q)));return pageHeader('The right words start here.','A complete prompt library for category pages, product research, editorial content and the work behind it.',btn('Export all prompts','export-prompts','download'))+`<div class="quiet-banner">${icon('pen')}<p><strong>Proposed working standards.</strong> These Wow Fashion prompts were created for this rebuild, informed by the current website and your existing portal workflows. They are ready for your editorial review.</p></div><div class="toolbar"><label class="field-search">${icon('search')}<span class="sr-only">Search prompts</span><input id="filter-query" data-filter="q" value="${e(filters.q)}" placeholder="Find a prompt by task, page type or keyword…"></label><select data-filter="promptGroup" aria-label="Prompt collection">${groups.map(g=>option(g,g,filters.promptGroup)).join('')}</select></div><div class="result-info"><span>${ps.length} prompts · Select one to add a brief, customise and copy</span><a href="#/guidelines">Read the writing standards</a></div>${ps.length?`<div class="prompt-grid">${ps.map(p=>`<a class="prompt-card" href="#/prompt/${e(p.id)}"><div class="prompt-category">${icon(/research|supplier/i.test(p.category)?'search':'pen')}${e(p.category)}</div><h2>${e(p.title)}</h2><p>${e(p.description)}</p><div class="card-footer"><span>${ws.promptOverrides[p.id]?'Custom workspace version':'Working template'} · ${p.inputs.length} brief inputs</span>${icon('arrow')}</div></a>`).join('')}</div>`:empty('No prompt found','Try a broader search or choose a different collection.','','','search')}`;}
const humanLabel=s=>s.replaceAll('_',' ').replace(/^./,c=>c.toUpperCase());
function promptBody(p){const v=ws.promptOverrides[p.id];return typeof v==='string'?v:v?.body||p.body;}
function commonContext(){return `Business model: ${ws.settings.businessModel==='undecided'?'UNDECIDED. Do not assume checkout, fulfilment or policies.':ws.settings.businessModel}\nTarget market: ${ws.settings.market}\nCurrency: ${ws.settings.currency}\nEditorial language: US English, proposed working default. Adapt when the brief specifies another locale.\nDo not invent current prices, supplier credentials, reviews, hands-on testing, quality guarantees or operating policies.`;}
let promptBuildState=null;
const briefStart='WOW FASHION BRIEF\n\n';
const briefDivider='\n\n---\n\n';
function promptContent(text){if(text.startsWith(briefStart)){const end=text.indexOf(briefDivider,briefStart.length);if(end!==-1)return text.slice(end+briefDivider.length);}return text;}
function fillPromptBody(base,values,keys){
 const accepted=new Set(keys),segments=[];let body='',cursor=0;
 const append=(start,end,text,replaced=false)=>{segments.push({baseStart:start,baseEnd:end,outStart:body.length,outEnd:body.length+text.length,replaced});body+=text;};
 for(const match of base.matchAll(/\{\{([A-Za-z0-9_]+)\}\}|\[([A-Za-z0-9_]+)\]/g)){
  const key=match[1]||match[2],value=values[key]?.trim();if(!accepted.has(key)||!value)continue;
  append(cursor,match.index,base.slice(cursor,match.index));append(match.index,match.index+match[0].length,value,true);cursor=match.index+match[0].length;
 }
 append(cursor,base.length,base.slice(cursor));return {body,segments};
}
function mergePromptEdits(state,current){
 if(!state||current===state.body)return state?.base??current;
 const old=state.body;let start=0,endOld=old.length,endCurrent=current.length;
 while(start<old.length&&start<current.length&&old[start]===current[start])start++;
 while(endOld>start&&endCurrent>start&&old[endOld-1]===current[endCurrent-1]){endOld--;endCurrent--;}
 let from=start,to=endOld;
 for(const segment of state.segments){if(!segment.replaced)continue;if(from>segment.outStart&&from<segment.outEnd)from=segment.outStart;if(to>segment.outStart&&to<segment.outEnd)to=segment.outEnd;}
 const baseOffset=offset=>{for(const segment of state.segments){if(offset===segment.outStart)return segment.baseStart;if(offset===segment.outEnd)return segment.baseEnd;if(!segment.replaced&&offset>segment.outStart&&offset<segment.outEnd)return segment.baseStart+offset-segment.outStart;}return state.base.length;};
 return state.base.slice(0,baseOffset(from))+old.slice(from,start)+current.slice(start,endCurrent)+old.slice(endOld,to)+state.base.slice(baseOffset(to));
}
function categoryBriefDefaults(cat){
 if(!cat)return {};
 const approved=ws.products.filter(p=>p.categoryId===cat.id&&p.status==='Approved').map(p=>`${p.name}: ${p.sourceUrl}\nEvidence checked: ${p.evidenceDate||'Not recorded'}\nEvidence: ${p.notes||p.gateNotes||'Not recorded'}`).join('\n\n')||'No approved products recorded. Do not invent recommendations.';
 return {category_name:cat.name,subcategory_name:cat.name,category_url:cat.url,subcategory_url:cat.url,parent_category:cat.parentName?`${cat.parentName}: ${cat.parentUrl}`:'Top-level category',subcategories:taxonomy.rows.filter(y=>y.parentId===cat.id).map(y=>`${y.name}: ${y.url}`).join('\n'),sibling_categories:taxonomy.rows.filter(y=>y.system===cat.system&&y.parentId===cat.parentId&&y.id!==cat.id).map(y=>`${y.name}: ${y.url}`).join('\n'),approved_products:approved,product_evidence:approved};
}
function promptView(r){const p=library.prompts.find(x=>x.id===r.id);if(!p)return empty('Prompt not found','Return to the writing prompt library.','','','pen');const selected=r.params.get('category');const cat=rowById(selected);const custom=ws.promptOverrides[p.id];const briefDefaults=categoryBriefDefaults(cat);promptBuildState=null;return `<a class="back-link" href="#/prompts">${icon('back')} Back to writing prompts</a>`+pageHeader(p.title,p.description,btn('Copy prompt','copy-prompt','copy','primary',`data-id="${e(p.id)}"`))+`<div class="detail-layout"><section><div class="section-head">${badge(custom?'Custom workspace version':'Proposed working template',custom?'green':'accent')}<span class="small muted">${e(p.category)}</span></div><textarea id="prompt-editor" class="prompt-editor" aria-label="Editable prompt text" spellcheck="false">${e(promptBody(p))}</textarea><div class="prompt-actions">${btn('Copy prompt','copy-prompt','copy','primary',`data-id="${e(p.id)}"`)}${btn('Save custom version','save-prompt','check','',`data-id="${e(p.id)}"`)}${btn('Download text','download-prompt','download','',`data-id="${e(p.id)}"`)}${custom?btn('Reset template','reset-prompt','refresh','small',`data-id="${e(p.id)}"`):''}</div><p class="footer-note">The builder prepares a reusable prompt for your chosen AI tool. It does not run a model or fetch live AliExpress data. Verify outputs against the evidence pack before publishing.</p>${p.output?`<div class="subsection"><h2>Expected output</h2><p class="footer-note">${e(Array.isArray(p.output)?p.output.join(' · '):p.output)}</p></div>`:''}</section><aside><div class="panel"><h2>Make it specific</h2><p class="small muted" style="margin-bottom:18px">Add the brief and apply it to the prompt. Fields you leave blank stay marked as not supplied.</p><form id="prompt-input-form" data-id="${e(p.id)}"><div class="prompt-inputs"><label class="field"><span>Use a mapped category</span><select name="mappedCategory">${categoryOptions(cat?.id||'')}</select></label>${p.inputs.filter(x=>!['commercial_mode','market_and_currency'].includes(x)).map(x=>{return textarea(humanLabel(x),x,briefDefaults[x]||'');}).join('')}</div><div class="form-actions">${btn('Apply brief to prompt','apply-prompt','arrow','primary','type="submit"')}</div></form></div><p class="footer-note">Market and business model come from <a href="#/settings">workspace settings</a>. Saving a custom version keeps it available across sessions.</p></aside></div>`;}
function guidelinesView(){return pageHeader('A point of view. A consistent voice.','The shared editorial and research standards behind every Wow Fashion page.',`<a class="btn primary" href="#/prompt/master-editorial-guidelines">${icon('copy')} Open master prompt</a>`)+`<div class="quiet-banner">${icon('book')}<p><strong>Proposed standard · version ${e(library.version)}.</strong> Built from the current brand and the supplied portal references. Business model, market, policies and testing claims still need owner confirmation.</p></div><div class="standards-layout"><nav class="standards-nav" aria-label="Guideline sections">${library.guidelines.map(g=>`<a href="#standard-${e(g.id)}" data-action="scroll-standard" data-id="${e(g.id)}">${e(g.title)}</a>`).join('')}</nav><div>${library.guidelines.map(g=>`<section class="standard-section" id="standard-${e(g.id)}"><h2>${e(g.title)}</h2><p>${e(g.summary)}</p><ul>${g.rules.map(rule=>`<li>${e(rule)}</li>`).join('')}</ul></section>`).join('')}</div></div>`;}
function roadmapView(){const all=roadPhases.flatMap(x=>x.tasks);const done=t=>Object.hasOwn(ws.roadmap,t[0])?ws.roadmap[t[0]]:t[3];const count=all.filter(done).length;return pageHeader('From the first edit to launch.','A practical build sequence, with research completed and the next decisions visible.',btn('Export checklist','export-roadmap','download'))+`<div class="section-head"><span class="small muted">${count} of ${all.length} milestones complete</span>${badge('Planning checklist','outline')}</div><div class="status-progress" style="margin-bottom:30px"><span style="width:${count/all.length*100}%"></span></div><div class="roadmap-grid">${roadPhases.map(p=>`<section class="roadmap-phase"><h2>${p.title}</h2><p>${p.desc}</p>${p.tasks.map(t=>`<label class="task-row ${done(t)?'done':''}"><input class="task-check" type="checkbox" data-task="${t[0]}" ${done(t)?'checked':''}><div><h3>${t[1]}</h3><p>${t[2]}</p></div></label>`).join('')}</section>`).join('')}</div><p class="footer-note">Task completion is a planning record. It does not change the live website, submit a supplier order or publish page copy.</p>`;}
function sourcesView(r){const tab=r.params.get('tab')||'findings';const refs=[['Affiliate Build OS','https://affiliate-websites-nu.vercel.app/','Page-led workbench, vendor research and writing workflow.'],['Flight master portal','https://find-a-cheap-flight-master-portal.vercel.app/','Inventory, release planning, priorities and evidence review.'],['MX page workspace','https://mx-page-workspace.vercel.app/','Sidebar workbench, page catalogue, editable briefs and connection status.'],['Writing guidelines portal','https://writing-guidelines-portal.vercel.app/','Shared tone, internal linking and SEO guidelines.'],['Wow Fashion homepage preview','https://wow-fashion-homepage.vercel.app/','Existing brand direction. Design reference, separate from the audited live website.'],['Wow Fashion dress edit','https://wow-fashion-dress-edit.vercel.app/','Existing editorial collection design.'],['Wow Fashion club dresses','https://wow-fashion-club-dresses.vercel.app/','Existing occasion-led category design.']];return pageHeader('Keep the thinking traceable.','Audit evidence, migration decisions and the references informing this workspace.')+`<div class="tabs" role="tablist" aria-label="Source collections">${[['findings','Migration findings'],['audit','Website evidence'],['research','Writing & sourcing sources'],['references','Portal & design references']].map(([id,label])=>`<button role="tab" aria-selected="${tab===id}" class="tab ${tab===id?'active':''}" data-action="source-tab" data-value="${id}">${label}</button>`).join('')}</div>${tab==='findings'?`<div class="quiet-banner warning">${icon('info')}<p>These are current-site observations for the rebuild. No live website configuration has been changed.</p></div>${taxonomy.findings.map(f=>`<article class="source-card">${badge(f.severity+' priority',f.severity==='High'?'amber':'')}<h3>${e(f.title)}</h3><p>${e(f.detail)}</p><div class="prompt-actions">${f.sources.map((s,i)=>link('Evidence '+(i+1),s,'external','link-btn')).join('')}</div></article>`).join('')}<section class="subsection"><h2>The five overlapping URLs</h2><div class="table-wrap" style="margin-top:17px"><table><thead><tr><th>URL</th><th>Records sharing this URL</th><th>Current response</th></tr></thead><tbody>${taxonomy.collisions.map(c=>`<tr><td>${e(new URL(c.url).pathname)}</td><td>${c.records.map(x=>`<a href="#/category/${e(x.id)}">${e(x.system)}: ${e(x.name)}${x.parentName?' / '+e(x.parentName):''}</a>`).join('<br>')}</td><td>${e(c.liveBehavior)}</td></tr>`).join('')}</tbody></table></div></section>`:tab==='audit'?`<div class="panel"><h2>What this inventory covers</h2><p class="small muted">All 132 published WordPress pages and all 135 WooCommerce category terms were paginated. The 113 editorial category pages include 7 parent pages and 106 children. Every child appears in the homepage directory and page sitemap. The two blog categories are kept separately.</p><p class="footer-note">248 commercial records represent 243 distinct URLs. Including blog categories gives 250 records and 245 URLs. Fifteen URLs were individually HTTP-checked. This is a public-source snapshot from 7 November 2026, not a full technical crawl or a guarantee that every endpoint currently returns the expected page.</p></div><div class="source-grid">${taxonomy.sources.map(s=>`<article class="source-card"><h3>${e(s.name)}</h3><p>First-party source · checked ${e(s.accessedAt)}</p>${link(s.url,s.url,'external','link-btn')}</article>`).join('')}</div>`:tab==='research'?`<div class="quiet-banner">${icon('source')}<p>New prompts are labelled as proposed. The existing reference portals supplied shared editorial patterns, not an approved Wow Fashion prompt pack.</p></div><div class="source-grid">${library.sources.map(s=>`<article class="source-card"><h3>${e(s.title||s.name)}</h3><p>${e(s.note||s.notes||'')}</p>${link(s.url,s.url,'external','link-btn')}<p class="small">Checked ${e(s.checkedAt||s.accessedAt||'2026-11-07')}</p></article>`).join('')}</div>`:`<div class="source-grid">${refs.map(([name,url,note])=>`<article class="source-card"><h3>${name}</h3><p>${note}</p>${link('Open reference',url,'external','link-btn')}</article>`).join('')}</div><p class="footer-note">References can have their own Vercel access requirements. The three Wow Fashion previews inform the visual direction; they are not counted as current wowfashion.com category pages.</p>`}`;}
function settingsView(){return pageHeader('Make the workspace your own.','Set the brief, manage shared access and keep a portable copy of your work.')+`<div class="settings-grid"><section class="panel"><h2>Working brief</h2><p>The current site has retail policies, while the rebuild references include affiliate workflows. Choose the new model deliberately.</p><form id="settings-form"><div class="form-grid">${selectField('Business model','businessModel',[['undecided','Undecided'],['affiliate','Affiliate publisher'],['retail','Direct retail'],['hybrid','Hybrid']],ws.settings.businessModel)}${selectField('Currency','currency',['GBP','USD','EUR','CAD','AUD'],ws.settings.currency)}${field('Target market','market',ws.settings.market,'text','required maxlength="120"')}</div><p class="footer-note">UK / GBP are planning defaults. The proposed writing standard uses US English to match the existing department language; change this in a brief where needed.</p><div id="form-error"></div><div class="form-actions">${btn('Save working brief','submit-settings','check','primary','type="submit"')}</div></form></section><section class="panel"><h2>Workspace data</h2><p>Supplier records, product research, page plans, customised prompts and milestones are shared between authorised sessions.</p><div class="prompt-actions">${btn('Export backup','export-workspace','download')}${btn('Restore backup','import-workspace','upload')}</div><input type="file" id="import-file" accept="application/json,.json" hidden><p class="footer-note">A backup contains your workspace records and should be kept privately. Restoring replaces the shared data after you confirm the contents.</p><div class="subsection"><h3>Access</h3><p class="footer-note">${authenticated?'This session is connected to the shared workspace.':'You are viewing the public reference material. Open the workspace to load private records.'}</p>${btn(authenticated?'Sign out':'Open workspace',authenticated?'logout':'unlock',authenticated?'lock':'unlock','small')}</div></section><section class="panel"><h2>Source and deployment</h2><p>The project is connected to your GitHub repository. Production changes can be deployed through Vercel.</p>${link('Open GitHub repository','https://github.com/m0veproperty/wow-fashion-new-website','external','link-btn')}<p class="footer-note">The source audit is a dated snapshot. Researching new AliExpress products uses the prompt library and evidence forms; there is no automatic marketplace feed or background crawler.</p></section><section class="panel"><h2>What is ready, what is proposed</h2><ul class="bullet-list"><li>The current public category inventory is source-verified.</li><li>The writing prompts and product scoring rubric are proposed standards for review.</li><li>Supplier and product approvals are manual evidence-based decisions.</li><li>The build roadmap is a planning tool, separate from live website changes.</li></ul></section></div>`;}
function showFormError(err){const scope=$('#dialog')?.open?$('#dialog'):document;const el=$('#form-error',scope);if(el)el.innerHTML=`<div class="form-error" role="alert">${e(err.message||err)}</div>`;else toast(err.message||String(err),true);}
let confirmAction=null,pendingImport=null;
function confirmDialog(title,message,callback){confirmAction=callback;openDialog(title,`<p>${e(message)}</p><div class="form-actions">${btn('Cancel','close-dialog')}${btn('Confirm','confirm-action','check','primary')}</div>`,true);}
function searchDialog(){openDialog('Find your next step',`<label class="field-search" style="display:block">${icon('search')}<span class="sr-only">Search workspace</span><input id="global-search" placeholder="A category, prompt, product or supplier…" autocomplete="off"></label><div id="search-results" class="search-results"></div>`);renderSearch('');}
function renderSearch(q){q=q.toLowerCase().trim();const data=[{title:'The Everyday Rib Cardigan',note:'Products · Test product layout',href:'#/product-pages',icon:'layers'},...taxonomy.rows.map(x=>({title:x.name,note:`${x.system} · ${x.path}`,href:`#/category/${x.id}`,icon:'map'})),...library.prompts.map(p=>({title:p.title,note:p.category,href:`#/prompt/${p.id}`,icon:'pen'})),...ws.products.map(p=>({title:p.name,note:'Product research',action:'edit-product',id:p.id,icon:'bag'})),...ws.suppliers.map(s=>({title:s.name,note:'Supplier directory',action:'edit-supplier',id:s.id,icon:'users'}))];const found=(q?data.filter(x=>(x.title+' '+x.note).toLowerCase().includes(q)):data.filter(x=>x.icon==='pen')).slice(0,20);$('#search-results').innerHTML=found.length?found.map(x=>`<${x.href?'a':'button'} class="search-result" ${x.href?`href="${e(x.href)}"`:`data-action="${x.action}" data-id="${e(x.id)}"`}>${icon(x.icon)}<div><h3>${e(x.title)}</h3><span class="small">${e(x.note)}</span></div></${x.href?'a':'button'}>`).join(''):'<p class="footer-note">No matches. Try a category name, URL fragment or writing task.</p>';}
function currentPrompt(){return library.prompts.find(x=>x.id===route().id);}
function exportProducts(){download('Wow_Fashion_Products.csv',csv([['Product','Supplier','AliExpress URL','Category IDs','Categories','Proposed keyword pages','Variation count','Currency','Minimum known variant price','Maximum known variant price','Incomplete prices','Reference price','Item rating /5','Rating count','Status','Evidence date','Notes'],...ws.products.map(p=>{const r=priceRange(p);return [p.name,ws.suppliers.find(s=>s.id===p.supplierId)?.name,p.sourceUrl,productCategories(p).join(' | '),productCategories(p).map(id=>rowById(id)?.name||id).join(' | '),(p.keywordTargets||[]).map(t=>t.keyword).join(' | '),p.variants?.length||0,p.currency,r.min,r.max,r.partial,p.price,p.rating,p.reviews,p.status,p.evidenceDate,p.notes];})]),'text/csv;charset=utf-8');}
function exportSuppliers(){download('Wow_Fashion_Suppliers.csv',csv([['Supplier','Store URL','Relationship','Country','Distinct products','Product records','Variation combinations','Weighted product rating /5','Rated products','Rating count','Products missing weighting data','Store rating /5','Mapped categories','Contact','Lead time','Shipping destinations','Order terms','Returns policy','Sample status','Supplier checked','Latest product check','Status','Notes'],...ws.suppliers.map(s=>{const a=supplierSummary(s.id,ws.products);return [s.name,s.url,s.type,s.country,a.products,a.records,a.variants,a.rating==null?'':a.rating.toFixed(2),a.ratedProducts,a.reviews,a.unratedProducts,s.rating,a.categories.map(id=>rowById(id)?.name||id).join(' | '),s.contact,s.leadTime,s.shippingDestinations,s.orderTerms,s.returnsPolicy,s.sampleStatus,s.checkedAt,a.latestCheck,s.status,s.notes];})]),'text/csv;charset=utf-8');}
function exportCategories(){const rows=[['System','Name','Existing URL','Parent','Level','Source ID','Source count','Count type','Source verified','HTTP status','Robots','Planning status','Priority','Owner','Proposed URL','Primary keyword','Target products','Notes','Has the page been built?','Does the page feature an animated header?','New page preview URL'],...taxonomy.rows.map(x=>{const p=planFor(x.id);return[x.system,x.name,x.url,x.parentName,x.level,x.sourceId,x.count,x.countType||'Not applicable',x.verificationStatus,x.httpStatus,x.robots,p.status||'Not started',p.priority,p.owner,p.proposedUrl,p.keyword,p.targetProducts,p.notes,p.pageBuilt,p.animatedHeader,p.previewUrl];})];download('Wow_Fashion_Category_Inventory.csv',csv(rows),'text/csv;charset=utf-8');}
function roadmapText(){return '# Wow Fashion build roadmap\n\n'+roadPhases.map(p=>`## ${p.title}\n\n${p.tasks.map(t=>`- [${(Object.hasOwn(ws.roadmap,t[0])?ws.roadmap[t[0]]:t[3])?'x':' '}] ${t[1]}: ${t[2]}`).join('\n')}`).join('\n\n');}
function requireRecords(callback){ensureAuth(callback);}
document.addEventListener('click',async ev=>{
 if(ev.target.closest('.skip-link')){ev.preventDefault();$('#main')?.focus();$('#main')?.scrollIntoView({block:'start'});return;}
 const a=ev.target.closest('[data-action]');
 if(ev.target.closest('a[href^="#/"]')&&$('#dialog').open&&!a?.dataset.action?.startsWith('close'))closeDialog();
 if(!a)return;
 const action=a.dataset.action;
 if(action.startsWith('submit-')||action==='apply-prompt')return;
 ev.preventDefault();
 try{
 switch(action){
 case 'menu':{const sh=$('.shell');sh.classList.toggle('menu-open');$('.menu-toggle')?.setAttribute('aria-expanded',sh.classList.contains('menu-open'));break;}
 case 'close-dialog':closeDialog();break;
 case 'close-for-link':closeDialog();location.hash=a.getAttribute('href');break;
 case 'unlock':unlock();break;
 case 'refresh':await loadWorkspace();shell();toast('Shared workspace refreshed');break;
 case 'logout':await api('/api/session',{method:'DELETE'});authenticated=false;ws=blank();etag=null;shell();toast('Signed out of the shared workspace');break;
 case 'search':searchDialog();break;
 case 'map-system':filters={q:'',department:'all',level:'all',status:'all',promptGroup:'All'};go('map',{system:a.dataset.value});break;
 case 'product-view':go('products',{view:a.dataset.value});break;
 case 'source-tab':go('sources',{tab:a.dataset.value});break;
 case 'reset-filters':filters={q:'',department:'all',level:'all',status:'all',promptGroup:'All'};go('map',{system:route().params.get('system')||'editorial'});renderMain();break;
 case 'export-categories':exportCategories();break;
 case 'add-product':openProduct('',a.dataset.category||(route().page==='category'?route().id:route().params.get('category'))||'');break;
 case 'edit-product':if($('#dialog').open)closeDialog();openProduct(a.dataset.id);break;
 case 'add-supplier':openSupplier();break;
 case 'edit-supplier':if($('#dialog').open)closeDialog();openSupplier(a.dataset.id);break;
 case 'export-products':requireRecords(exportProducts);break;
 case 'export-variants':requireRecords(exportVariants);break;
 case 'add-variant':$('#variant-rows').insertAdjacentHTML('beforeend',variantRow({id:uid()}));break;
 case 'remove-variant':a.closest('[data-variant-row]').remove();updateProductScore();break;
 case 'add-keyword-target':{const p=collectionResearch?.proposals.find(x=>x.slug===a.dataset.slug);if(p&&!productKeywordDraft.some(t=>t.slug===p.slug)){const g=collectionResearch.groups[p.group];productKeywordDraft.push({slug:p.slug,keyword:p.keyword,categoryId:g.ids[0]});renderProductKeywordPicker();}break;}
 case 'remove-keyword-target':productKeywordDraft=productKeywordDraft.filter(t=>t.slug!==a.dataset.slug);renderProductKeywordPicker();break;
 case 'retry-collection-research':collectionResearchError='';loadCollectionResearch().then(()=>{if($('#product-form'))renderProductKeywordPicker();else renderMain();});break;
 case 'export-suppliers':requireRecords(exportSuppliers);break;
 case 'delete-product':{const id=a.dataset.id;confirmDialog('Delete this product?','This removes the product research record from the shared workspace. Export a backup first if you need to keep it.',async()=>{await saveWorkspace(d=>{d.products=d.products.filter(p=>p.id!==id);},'Product record deleted');closeDialog();renderMain();});break;}
 case 'delete-supplier':{const id=a.dataset.id;if(ws.products.some(p=>p.supplierId===id)){toast('Unlink this supplier from its products before deleting the record.',true);break;}confirmDialog('Delete this supplier?','This removes the supplier record and its notes from the shared workspace.',async()=>{await saveWorkspace(d=>{d.suppliers=d.suppliers.filter(s=>s.id!==id);},'Supplier record deleted');closeDialog();renderMain();});break;}
 case 'confirm-action':if(confirmAction){const cb=confirmAction;confirmAction=null;await cb();}break;
 case 'category-prompt':{const x=rowById(a.dataset.id);go('prompt/'+(x.isTopLevel?'category-page':'subcategory-page'),{category:x.id});break;}
 case 'copy-prompt':await copy($('#prompt-editor').value,'Prompt copied. Ready for your AI writing tool.');break;
 case 'save-prompt':{const id=a.dataset.id;const body=$('#prompt-editor').value;ensureAuth(async()=>{try{await saveWorkspace(d=>{d.promptOverrides[id]={body,updatedAt:new Date().toISOString()};},'Custom prompt saved');renderMain();}catch(err){showFormError(err);}});break;}
 case 'download-prompt':download(`Wow_Fashion_${a.dataset.id}.txt`,$('#prompt-editor').value,'text/plain;charset=utf-8');break;
 case 'reset-prompt':{const id=a.dataset.id;ensureAuth(()=>confirmDialog('Restore the original template?','Your custom version will be replaced by the proposed working template.',async()=>{await saveWorkspace(d=>{delete d.promptOverrides[id];},'Prompt restored to its original template');closeDialog();renderMain();}));break;}
 case 'export-prompts':download('Wow_Fashion_Prompt_Library.md','# Wow Fashion prompt library\n\nProposed working standards. Audit date: 7 November 2026.\n\n'+library.prompts.map(p=>`## ${p.title}\n\n${promptBody(p)}`).join('\n\n---\n\n'),'text/markdown;charset=utf-8');break;
 case 'scroll-standard':document.getElementById('standard-'+a.dataset.id)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'});break;
 case 'export-roadmap':download('Wow_Fashion_Build_Roadmap.md',roadmapText(),'text/markdown;charset=utf-8');break;
 case 'export-workspace':requireRecords(()=>download(`Wow_Fashion_Workspace_${today()}.json`,JSON.stringify({exportedAt:new Date().toISOString(),application:'wow-fashion-portal',data:ws},null,2)));break;
 case 'import-workspace':requireRecords(()=>$('#import-file').click());break;
 }
 }catch(err){showFormError(err);}
});
let filterTimer;
document.addEventListener('input',ev=>{
 const t=ev.target;
 if(t.id==='global-search'){renderSearch(t.value);return;}
 if(t.id==='keyword-product-search'){renderProductKeywordResults(t.value);return;}
 if(t.closest('#product-form'))updateProductScore();
 if(t.dataset.filter==='q'){filters.q=t.value;const pos=t.selectionStart;clearTimeout(filterTimer);filterTimer=setTimeout(()=>{renderMain();const input=$('#filter-query');input?.focus();input?.setSelectionRange(pos,pos);},130);}
});
document.addEventListener('change',async ev=>{
 const t=ev.target;
 if(t.name==='categoryId'&&t.closest('#product-form')){renderProductKeywordResults($('#keyword-product-search')?.value||'');return;}
 if(t.dataset.filter&&t.dataset.filter!=='q'){filters[t.dataset.filter]=t.value;if(t.dataset.filter==='department'){go('map',{system:route().params.get('system')||'editorial',...(t.value==='all'?{}:{department:t.value})});}else renderMain();return;}
 if(t.dataset.action==='product-category-filter'){go('products',{...(t.value?{category:t.value}:{}),...(route().params.get('supplier')?{supplier:route().params.get('supplier')}:{})});return;}
 if(t.dataset.action==='product-supplier-filter'){go('products',{...(t.value?{supplier:t.value}:{}),...(route().params.get('category')?{category:route().params.get('category')}:{})});return;}
 if(t.dataset.task){const id=t.dataset.task;const checked=t.checked;if(!authenticated){t.checked=!checked;unlock();return;}try{await saveWorkspace(d=>{d.roadmap[id]=checked;},(checked?'Completed: ':'Reopened: ')+roadPhases.flatMap(x=>x.tasks).find(x=>x[0]===id)?.[1]);renderMain();}catch(err){t.checked=!checked;toast(err.message,true);}return;}
 if(t.name==='mappedCategory'){const x=rowById(t.value);if(!x)return;const f=t.closest('form');for(const [name,value] of Object.entries(categoryBriefDefaults(x)))if(f.elements[name])f.elements[name].value=value;return;}
 if(t.id==='import-file'&&t.files[0]){try{if(t.files[0].size>2*1024*1024)throw new Error('This backup is larger than the 2 MB workspace limit.');const data=JSON.parse(await t.files[0].text());if(data.application!=='wow-fashion-portal'||data.data?.schemaVersion!==1||!Array.isArray(data.data.products)||!Array.isArray(data.data.suppliers))throw new Error('Choose a valid Wow Fashion workspace backup.');pendingImport=data.data;confirmDialog('Restore this workspace backup?',`This will replace the shared records with ${pendingImport.products.length} products, ${pendingImport.suppliers.length} suppliers and ${Object.keys(pendingImport.pagePlans||{}).length} page plans. Export the current workspace first if you need to retain it.`,async()=>{await saveWorkspace(d=>{for(const key of ['products','suppliers','pagePlans','promptOverrides','roadmap','settings','activity'])d[key]=structuredClone(pendingImport[key]??blank()[key]);},'Workspace restored from backup');pendingImport=null;closeDialog();renderMain();});}catch(err){toast(err.message,true);}finally{t.value='';}}
});
document.addEventListener('submit',async ev=>{
 const form=ev.target;if(!['login-form','page-plan-form','product-form','supplier-form','prompt-input-form','settings-form'].includes(form.id))return;ev.preventDefault();const submit=form.querySelector('[type=submit]');if(submit)submit.disabled=true;const errBox=form.querySelector('#form-error');if(errBox)errBox.innerHTML='';
 try{
 if(form.id==='login-form'){await api('/api/session',{method:'POST',body:JSON.stringify({code:form.elements.code.value})});authenticated=true;await loadWorkspace();const next=pendingAction;pendingAction=null;closeDialog();shell();toast('Shared workspace opened');if(next)await next();return;}
 if(form.id==='prompt-input-form'){const p=currentPrompt();const values=Object.fromEntries(new FormData(form));values.commercial_mode=ws.settings.businessModel==='undecided'?'UNDECIDED: ask for the operating model before making transactional claims':ws.settings.businessModel;values.market_and_currency=`${ws.settings.market} · ${ws.settings.currency}`;const inputs=p.inputs.map(k=>`${humanLabel(k)}:\n${values[k]?.trim()||'[NOT SUPPLIED: request this information or leave an explicit placeholder.]'}`).join('\n\n');const editor=$('#prompt-editor');const current=promptContent(editor.value);const base=mergePromptEdits(promptBuildState?.id===p.id?promptBuildState:null,current);const filled=fillPromptBody(base,values,p.inputs);promptBuildState={id:p.id,base,...filled};editor.value=`${briefStart}${commonContext()}\n\n${inputs}${briefDivider}${filled.body}`;toast('Brief added to the prompt');return;}
 if(form.id==='page-plan-form'){const d=Object.fromEntries(new FormData(form));d.targetProducts=Number(d.targetProducts);d.updatedAt=new Date().toISOString();const id=form.dataset.id;const save=async()=>{try{await saveWorkspace(w=>{w.pagePlans[id]={...(w.pagePlans[id]||{}),...d};},'Page plan saved: '+rowById(id).name);renderMain();}catch(err){showFormError(err);}};if(authenticated)await save();else unlock(save);return;}
 if(form.id==='settings-form'){const d=Object.fromEntries(new FormData(form));const save=async()=>{try{await saveWorkspace(w=>{w.settings=d;},'Working brief updated');renderMain();}catch(err){showFormError(err);}};if(authenticated)await save();else unlock(save);return;}
 if(form.id==='product-form'){const data=productFormData(form);if(data.evidenceDate>today())throw new Error('The evidence date cannot be in the future.');if(data.hardGate==='clear'&&!data.gateNotes.trim())throw new Error('Record the evidence behind your critical checks before marking them passed.');if(data.status==='Approved'&&!scoreProduct(data).approvalEligible)throw new Error('This product is not ready for approval. Complete current evidence and reach Priority shortlist, then record the review decision.');const existing=ws.products.find(x=>x.id===form.dataset.id);const record={...existing,...data,id:existing?.id||uid(),createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};await saveWorkspace(w=>{const i=w.products.findIndex(x=>x.id===record.id);if(i>=0)w.products[i]=record;else w.products.push(record);},'Product research saved: '+record.name);closeDialog();renderMain();return;}
 if(form.id==='supplier-form'){const data=Object.fromEntries(new FormData(form));data.rating=data.rating===''?null:Number(data.rating);if(data.checkedAt>today())throw new Error('The check date cannot be in the future.');if(data.type==='Manufacturer verified'&&(!data.manufacturingEvidence.trim()||!data.evidenceUrl||!data.checkedAt))throw new Error('Add manufacturer evidence, a source URL and a check date before verifying manufacturing status.');if(data.status==='Approved'&&(!data.notes.trim()||!data.checkedAt))throw new Error('Record your due diligence notes and check date before approving a supplier.');const existing=ws.suppliers.find(x=>x.id===form.dataset.id);const record={...existing,...data,id:existing?.id||uid(),createdAt:existing?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};await saveWorkspace(w=>{const i=w.suppliers.findIndex(x=>x.id===record.id);if(i>=0)w.suppliers[i]=record;else w.suppliers.push(record);},'Supplier record saved: '+record.name);closeDialog();renderMain();return;}
 }catch(err){showFormError(err);}finally{if(submit?.isConnected)submit.disabled=false;}
});
document.addEventListener('keydown',ev=>{if((ev.metaKey||ev.ctrlKey)&&ev.key.toLowerCase()==='k'){ev.preventDefault();searchDialog();}});
$('#dialog').addEventListener('click',ev=>{const d=$('#dialog');if(ev.target===d){const rect=d.getBoundingClientRect();if(ev.clientX<rect.left||ev.clientX>rect.right||ev.clientY<rect.top||ev.clientY>rect.bottom)closeDialog();}});
$('#dialog').addEventListener('cancel',()=>{pendingAction=null;returnFocus?.focus?.();});
window.addEventListener('hashchange',()=>{const r=route();const key=r.page+'/'+r.id;if(key!==renderedRoute){filters={q:'',department:'all',level:'all',status:'all',promptGroup:'All'};renderedRoute=key;}if(taxonomy&&library){shell();window.scrollTo(0,0);}});
async function init(){try{[taxonomy,library,buildStatus]=await Promise.all(['/data/taxonomy.json','/data/prompts.json','/data/build-status.json'].map(async url=>{const r=await fetch(url);if(!r.ok)throw new Error('Reference content could not be loaded.');return r.json();}));try{const session=await api('/api/session');authenticated=session.authenticated;localPreview=!!session.localPreview;if(authenticated)await loadWorkspace();}catch(err){authenticated=false;}renderedRoute=route().page+'/'+route().id;shell();}catch(err){$('#app').innerHTML=`<div class="initial-loading"><span class="wordmark">WOW<span>FASHION</span></span><p>${e(err.message)}</p><a class="btn primary" href="/">Reload workspace</a></div>`;}}
let collectionResearch=null,collectionResearchLoading=null,collectionResearchError='',productKeywordDraft=[];
async function loadCollectionResearch(){if(collectionResearch)return collectionResearch;if(collectionResearchLoading)return collectionResearchLoading;collectionResearchError='';collectionResearchLoading=(async()=>{const read=async url=>{const res=await fetch(url);if(!res.ok)throw Error('Keyword page ideas could not be loaded.');return res.json();};const data=await read('/data/keyword-research.json');const proposals=(await Promise.all(data.meta.proposalFiles.map(read))).flat();collectionResearch={...data,proposals};return collectionResearch;})().catch(err=>{collectionResearchError=err.message;return null;}).finally(()=>{collectionResearchLoading=null;if(route().page==='products'&&!$('#dialog').open)renderMain();});return collectionResearchLoading;}
function productMappingFields(p){const selected=productCategories(p);return `<div class="form-section"><h3>Map this product to pages</h3><p>One product can appear on several relevant pages. The primary category above is retained for existing briefs.</p></div><label class="field"><span>Additional categories</span><select name="multiCategoryIds" multiple size="7" class="category-multiselect">${taxonomy.rows.filter(r=>r.system!=='blog').map(r=>`<option value="${e(r.id)}" ${selected.includes(r.id)?'selected':''}>${e(r.system+' · '+r.rootName+' / '+r.name)}</option>`).join('')}</select><small>Hold Ctrl (Windows) or Command (Mac) to select several categories.</small></label><div class="form-section"><h3>Keyword-led sub-subcategories</h3><p>Link relevant page ideas such as brown leather jacket. These remain proposed pages until the category plan is approved. Only link a page when this listing has a matching variation.</p></div><div id="product-keyword-picker"><p class="small muted">Loading keyword page ideas…</p></div>`;}
function productVariationFields(p){return `<div class="form-section"><h3>Variations and prices</h3><p>Each row is one actual purchasable combination, for example brown / biker / M. Prices use the product currency above and exclude shipping. Leave unverified prices blank.</p></div><div id="variant-rows">${(p.variants||[]).map(variantRow).join('')}</div>${btn('Add variation combination','add-variant','plus','small','type="button"')}<p class="footer-note">With no variation rows, the reference price is displayed. Once variations exist, the catalogue price range uses their known prices and flags missing values.</p>`;}
function variantRow(v){const input=(label,key,type='text')=>`<label class="field"><span>${label}</span><input data-variant-field="${key}" aria-label="Variation ${label.toLowerCase()}" type="${type}" value="${e(v[key]??'')}" ${type==='number'?'min="0" step="0.01"':'maxlength="200"'}></label>`;return `<section class="variant-editor" data-variant-row="${e(v.id)}"><div class="form-grid">${input('Colour','colour')}${input('Style','style')}${input('Size','size')}${input('Other option','option')}${input('SKU / variant ID','sku')}${input('Price','price','number')}<label class="field"><span>Availability</span><select data-variant-field="availability">${['Unknown','Available','Out of stock','Discontinued'].map(x=>option(x,x,v.availability||'Unknown')).join('')}</select></label><div>${btn('Remove combination','remove-variant','trash','small danger','type="button"')}</div></div></section>`;}
async function loadProductKeywordPicker(){const form=$('#product-form');await loadCollectionResearch();if(!form?.isConnected)return;const slug=route().params.get('keyword');const p=collectionResearch?.proposals.find(x=>x.slug===slug);if(p&&!form.dataset.id&&!productKeywordDraft.some(t=>t.slug===slug))productKeywordDraft.push({slug:p.slug,keyword:p.keyword,categoryId:collectionResearch.groups[p.group].ids[0]});renderProductKeywordPicker();}
function renderProductKeywordPicker(){const el=$('#product-keyword-picker');if(!el)return;const q=$('#keyword-product-search')?.value||'';el.innerHTML=`<div class="keyword-selected">${productKeywordDraft.map(t=>`<span class="keyword-chip">${e(t.keyword)} <button type="button" data-action="remove-keyword-target" data-slug="${e(t.slug)}" aria-label="Remove ${e(t.keyword)}">×</button></span>`).join('')||'<p class="small muted">No keyword-led pages linked yet.</p>'}</div>${collectionResearch?`<label class="field"><span>Find a keyword-led page</span><input id="keyword-product-search" value="${e(q)}" placeholder="e.g. brown leather jacket"></label><div id="product-keyword-results"></div>`:`<p class="small">${e(collectionResearchError||'Loading page ideas…')}</p>${btn('Retry','retry-collection-research','refresh','small','type="button"')}`}`;renderProductKeywordResults(q);}
function renderProductKeywordResults(q=''){const el=$('#product-keyword-results');if(!el||!collectionResearch)return;const words=q.toLowerCase().trim().split(/\s+/).filter(Boolean),primary=$('#product-form')?.elements.categoryId.value;const matches=collectionResearch.proposals.filter(p=>!productKeywordDraft.some(t=>t.slug===p.slug)&& (words.length?words.every(w=>(p.keyword+' '+p.variants.join(' ')).includes(w)):!primary||p.groups.some(i=>collectionResearch.groups[i].ids.includes(primary))));el.innerHTML=`<p class="small muted">${fmt(matches.length)} matches${matches.length>30?' · showing 30; type to narrow the list':''}</p><div class="keyword-results">${matches.slice(0,30).map(p=>`<button type="button" class="keyword-result" data-action="add-keyword-target" data-slug="${e(p.slug)}"><span>${e(p.keyword)}<small>${e(collectionResearch.groups[p.group].name)}</small></span><span>${fmt(p.volume)} UK / month · Add</span></button>`).join('')||'<p class="small muted">No matching page ideas. Try another phrase.</p>'}</div>`;}
function collectionCoverage(view){const q=filters.q.toLowerCase().trim();let items;if(view==='keyword-map'){if(!collectionResearch)return `<div class="panel"><p>${e(collectionResearchError||'Loading proposed page mappings…')}</p>${collectionResearchError?btn('Retry','retry-collection-research','refresh','small'):''}</div>`;items=collectionResearch.proposals.filter(p=>!q||(p.keyword+' '+collectionResearch.groups[p.group].name).includes(q));}else items=taxonomy.rows.filter(r=>r.system!=='blog'&&!r.isTopLevel&&(!q||(r.name+' '+r.rootName).toLowerCase().includes(q)));const keyword=view==='keyword-map';return `<div class="toolbar"><label class="field-search">${icon('search')}<span class="sr-only">Search page coverage</span><input id="filter-query" data-filter="q" value="${e(filters.q)}" placeholder="Search ${keyword?'keyword-led pages':'subcategories'}…"></label></div><p class="footer-note">${keyword?'Proposed pages from Keyword Research. Linked product counts do not approve a page or verify that its variants match.':'Existing editorial and shop records are kept separate. A single product can be linked to both where appropriate.'}</p><div class="result-info">${fmt(items.length)} pages${keyword&&items.length>100?' · showing 100; search to narrow':''}</div><div class="table-wrap"><table><thead><tr><th>Page</th><th>Parent / system</th>${keyword?'<th>UK searches / month</th>':''}<th>Linked products</th><th>Action</th></tr></thead><tbody>${items.slice(0,keyword?100:1000).map(r=>{const parent=keyword?collectionResearch.groups[r.group]:null;const count=ws.products.filter(p=>keyword?(p.keywordTargets||[]).some(t=>t.slug===r.slug):productCategories(p).includes(r.id)).length;return `<tr><td>${keyword?e(r.keyword):`<a href="#/category/${e(r.id)}">${e(r.name)}</a>`}</td><td>${e(keyword?parent.name:r.rootName+' · '+r.system)}</td>${keyword?`<td>${fmt(r.volume)}</td>`:''}<td>${authenticated?count:'Open workspace to view'}</td><td><a class="btn small" href="#/products?${keyword?'keyword='+e(r.slug)+'&category='+e(parent.ids[0]):'category='+e(r.id)}">View / add products</a></td></tr>`;}).join('')}</tbody></table></div>`;}
function exportVariants(){download('Wow_Fashion_Product_Variations.csv',csv([['Product ID','Product','Supplier','AliExpress URL','Variation ID','Colour','Style','Size','Other option','SKU','Price','Currency','Availability','Categories','Proposed keyword pages'],...ws.products.flatMap(p=>(p.variants||[]).map(v=>[p.id,p.name,ws.suppliers.find(s=>s.id===p.supplierId)?.name,p.sourceUrl,v.id,v.colour,v.style,v.size,v.option,v.sku,v.price,p.currency,v.availability,productCategories(p).map(id=>rowById(id)?.name||id).join(' | '),(p.keywordTargets||[]).map(t=>t.keyword).join(' | ')]))]),'text/csv;charset=utf-8');}

init();


